#define NVEC (sizeof(k256_vectors) / sizeof(k256_vectors[0]))
#define NDH (sizeof(dh_vectors) / sizeof(dh_vectors[0]))

static int expect(const char *name, bool got, bool want) {
  if (got != want) {
    printf("  FAIL %s (got %d, expected %d)\n", name, got, want);
    return 1;
  }
  printf("  ok   %s\n", name);
  return 0;
}

int main(void) {
  int r = 0;
  uint8_t out[65], tmp[64];
  char name[64];

  printf("K-256\n");

  for (size_t i = 0; i < NVEC; i++) {
    const k256_vec *v = &k256_vectors[i];

    snprintf(name, sizeof name, "private key %zu valid", i);
    r |= expect(name, Hacl_K256_Key_validate_private_key((uint8_t *)v->sk), true);

    snprintf(name, sizeof name, "public key %zu valid", i);
    r |= expect(name, Hacl_K256_Key_Public_validate_public_key((uint8_t *)v->pk), true);

    snprintf(name, sizeof name, "secret to public %zu", i);
    r |= expect(name, Hacl_K256_Ecdh_dh_initiator(out, (uint8_t *)v->sk), true);
    r |= check(name, out, v->pk, 64);

    snprintf(name, sizeof name, "sign %zu", i);
    r |= expect(name,
                Hacl_K256_ecdsa_sign_sha256(out, (uint8_t *)v->msg, v->msg_len,
                                            (uint8_t *)v->sk,
                                            (uint8_t *)v->nonce),
                true);
    r |= check(name, out, v->sig, 64);

    snprintf(name, sizeof name, "verify %zu", i);
    r |= expect(name,
                Hacl_K256_ecdsa_verify_sha256((uint8_t *)v->msg, v->msg_len,
                                              (uint8_t *)v->pk,
                                              (uint8_t *)v->sig,
                                              (uint8_t *)v->sig + 32),
                true);

    snprintf(name, sizeof name, "sign low-S %zu", i);
    r |= expect(name,
                Hacl_K256_secp256k1_ecdsa_sign_sha256(
                    out, (uint8_t *)v->msg, v->msg_len, (uint8_t *)v->sk,
                    (uint8_t *)v->nonce),
                true);
    r |= check(name, out, v->low, 64);

    snprintf(name, sizeof name, "verify low-S %zu", i);
    r |= expect(name,
                Hacl_K256_secp256k1_ecdsa_verify_sha256(
                    (uint8_t *)v->msg, v->msg_len, (uint8_t *)v->pk,
                    (uint8_t *)v->low, (uint8_t *)v->low + 32),
                true);

    /* The low-S family accepts a signature exactly when it is already
       normalised; the plain family accepts it either way. */
    bool already = memcmp(v->sig, v->low, 64) == 0;
    snprintf(name, sizeof name, "is normalized %zu", i);
    r |= expect(name, Hacl_K256_LowS_is_signature_normalized((uint8_t *)v->sig),
                already);

    snprintf(name, sizeof name, "high-S rejected %zu", i);
    r |= expect(name,
                Hacl_K256_secp256k1_ecdsa_verify_sha256(
                    (uint8_t *)v->msg, v->msg_len, (uint8_t *)v->pk,
                    (uint8_t *)v->sig, (uint8_t *)v->sig + 32),
                already);

    memcpy(tmp, v->sig, 64);
    snprintf(name, sizeof name, "normalize %zu", i);
    r |= expect(name, Hacl_K256_LowS_signature_normalize(tmp), true);
    r |= check(name, tmp, v->low, 64);

    /* Hashing separately must agree with hashing inside. */
    uint8_t h[32];
    Hacl_Hash_SHA2_sha256(h, (uint8_t *)v->msg, v->msg_len);
    snprintf(name, sizeof name, "sign hashed %zu", i);
    r |= expect(name,
                Hacl_K256_ecdsa_sign_hashed_msg(out, h, (uint8_t *)v->sk,
                                                (uint8_t *)v->nonce),
                true);
    r |= check(name, out, v->sig, 64);

    snprintf(name, sizeof name, "verify hashed %zu", i);
    r |= expect(name,
                Hacl_K256_ecdsa_verify_hashed_msg(h, (uint8_t *)v->pk,
                                                  (uint8_t *)v->sig,
                                                  (uint8_t *)v->sig + 32),
                true);

    /* SEC1 round trips. */
    Hacl_K256_Sec1_raw_to_uncompressed(out, (uint8_t *)v->pk);
    snprintf(name, sizeof name, "raw to uncompressed %zu", i);
    r |= check(name, out, v->unc, 65);

    snprintf(name, sizeof name, "uncompressed to raw %zu", i);
    r |= expect(name, Hacl_K256_Sec1_uncompressed_to_raw(tmp, (uint8_t *)v->unc),
                true);
    r |= check(name, tmp, v->pk, 64);

    Hacl_K256_Sec1_raw_to_compressed(out, (uint8_t *)v->pk);
    snprintf(name, sizeof name, "raw to compressed %zu", i);
    r |= check(name, out, v->cmpr, 33);

    snprintf(name, sizeof name, "compressed to raw %zu", i);
    r |= expect(name, Hacl_K256_Sec1_compressed_to_raw(tmp, (uint8_t *)v->cmpr),
                true);
    r |= check(name, tmp, v->pk, 64);
  }

  for (size_t i = 0; i < NDH; i++) {
    const k256_dh *d = &dh_vectors[i];
    snprintf(name, sizeof name, "ecdh %zu", i);
    r |= expect(name,
                Hacl_K256_Ecdh_dh_responder(out, (uint8_t *)d->pk,
                                            (uint8_t *)d->sk),
                true);
    r |= check(name, out, d->shared, 64);
  }

  /* Rejections. */
  {
    const k256_vec *v = &k256_vectors[2];
    uint8_t bad[64];

    memcpy(bad, v->sig, 64);
    bad[63] ^= 1;
    r |= expect("tampered signature rejected",
                Hacl_K256_ecdsa_verify_sha256((uint8_t *)v->msg, v->msg_len,
                                              (uint8_t *)v->pk, bad, bad + 32),
                false);

    r |= expect("wrong message rejected",
                Hacl_K256_ecdsa_verify_sha256((uint8_t *)v->msg,
                                              v->msg_len - 1, (uint8_t *)v->pk,
                                              (uint8_t *)v->sig,
                                              (uint8_t *)v->sig + 32),
                false);

    memset(bad, 0, 64);
    r |= expect("zero scalar rejected", Hacl_K256_Key_validate_private_key(bad),
                false);
    r |= expect("zero signature rejected",
                Hacl_K256_ecdsa_verify_sha256((uint8_t *)v->msg, v->msg_len,
                                              (uint8_t *)v->pk, bad, bad + 32),
                false);
    r |= expect("zero s not normalized",
                Hacl_K256_LowS_is_signature_normalized(bad), false);
    r |= expect("zero s not normalizable",
                Hacl_K256_LowS_signature_normalize(bad), false);

    memset(bad, 0xff, 64);
    r |= expect("out of range scalar rejected",
                Hacl_K256_Key_validate_private_key(bad), false);

    memcpy(bad, v->pk, 64);
    bad[0] ^= 1;
    r |= expect("off-curve public key rejected",
                Hacl_K256_Key_Public_validate_public_key(bad), false);

    memcpy(out, v->unc, 65);
    out[0] = 0x05;
    r |= expect("bad SEC1 header rejected",
                Hacl_K256_Sec1_uncompressed_to_raw(tmp, out), false);

    memcpy(out, v->cmpr, 33);
    out[0] = 0x05;
    r |= expect("bad compressed header rejected",
                Hacl_K256_Sec1_compressed_to_raw(tmp, out), false);
  }

  if (r)
    printf("K-256: FAILED\n");
  return r;
}
